// Helper function to count valid digits in the array
function CountDigits(arr: array<int>): int
    requires arr != null
    reads arr
    ensures 0 <= CountDigits(arr) <= |arr|
{
    var count := 0;
    var i := 0;
    while i < |arr|
        invariant 0 <= i <= |arr|
        invariant count == CountValidDigits(arr, i)
    {
        if arr[i] >= 1 && arr[i] <= 9 {
            count := count + 1;
        }
        i := i + 1;
    }
    return count;
}

// Helper function to count valid digits up to index
function CountValidDigits(arr: array<int>, index: int): int
    requires arr != null && 0 <= index <= |arr|
    reads arr
{
    var count := 0;
    var i := 0;
    while i < index
        invariant 0 <= i <= index
        invariant count == CountValidDigits(arr, i)
    {
        if arr[i] >= 1 && arr[i] <= 9 {
            count := count + 1;
        }
        i := i + 1;
    }
    return count;
}

